// Full holder-consent journey through the real React UI (SOV-041).
// The holder key is generated by WebCrypto in the page, exported via
// the real clipboard button, and every decision is signed in the
// page; Node only plays the server-side actors (issuer, RP) plus
// JWK plumbing that the UI itself cannot do.

import { expect } from '@playwright/test'
import type { Page } from '@playwright/test'
import {
  AUDIENCE,
  PURPOSE,
  RP_ID,
  createRequest,
  issueCredential,
  publicJwkFromPrivate,
  thumbprint,
} from './sovra'
import type { CreatedRequest, EcJwk, MachineSetup } from './sovra'

export interface Approval {
  requestId: string
  audience: string
  thumbprint: string
  privateJwk: EcJwk
}

export function expectedProfile(): string {
  return process.env.SOVRA_PROFILE === 'sdjwt-vc'
    ? 'sovra-g1-sdjwt-vc/0.2'
    : 'sovra-g1-synthetic/0.2'
}

async function fieldValue(page: Page, label: string): Promise<string> {
  const dd = page
    .locator('.consent-field', { has: page.locator('dt', { hasText: label }) })
    .locator('dd')
  return ((await dd.first().textContent()) ?? '').trim()
}

/** Generate a holder key in the page and export it via the UI. */
export async function browserHolder(
  page: Page,
): Promise<{ thumbprint: string; privateJwk: EcJwk & { d: string } }> {
  await page.goto('/')
  await page.getByRole('button', { name: 'Holder consent' }).click()
  await expect(page.getByLabel(/browser session/)).toBeChecked()
  await page.getByRole('button', { name: 'Generate holder key' }).click()
  const line = page.locator('code.mono').first()
  await expect(line).toContainText('holder: ')
  const displayed = ((await line.textContent()) ?? '').replace('holder: ', '').trim()
  await page.getByRole('button', { name: 'Copy private JWK' }).click()
  let pasted = ''
  for (let i = 0; i < 20 && pasted === ''; i++) {
    await page.waitForTimeout(250)
    pasted = await page.evaluate(() => navigator.clipboard.readText().catch(() => ''))
  }
  if (pasted === '') throw new Error('holder JWK clipboard export never landed')
  const privateJwk = JSON.parse(pasted) as EcJwk
  if (typeof privateJwk.d !== 'string' || privateJwk.d === '') {
    throw new Error('exported holder JWK lacks the private half')
  }
  const derived = publicJwkFromPrivate(privateJwk.d)
  expect(thumbprint(derived)).toBe(displayed)
  return { thumbprint: displayed, privateJwk: { ...privateJwk, d: privateJwk.d } }
}

/** Load a request in the consent UI and check every bound value. */
export async function reviewRequest(
  page: Page,
  created: CreatedRequest,
  holderThumb: string,
): Promise<void> {
  await page.getByLabel('Proof request id').fill(created.requestId)
  await page.getByRole('button', { name: 'Load request' }).click()
  await expect(page.getByText('Pending — awaiting your decision')).toBeVisible()
  await page.getByRole('button', { name: 'Review details' }).click()
  await expect(page.getByText('Review — check every bound value')).toBeVisible()
  expect(await fieldValue(page, 'Relying party')).toBe(RP_ID)
  expect(await fieldValue(page, 'Audience')).toBe(AUDIENCE)
  expect(await fieldValue(page, 'Purpose')).toBe(PURPOSE)
  expect(await fieldValue(page, 'Exact claims')).toBe('{"adultOver18":true}')
  expect(await fieldValue(page, 'Plan hash')).toBe(created.planHash)
  expect(await fieldValue(page, 'Challenge')).toBe(created.challenge)
  expect(await fieldValue(page, 'Expected holder')).toBe(holderThumb)
}

/**
 * End-to-end consent decision through the browser. Assumes the page
 * holds a logged-in session.
 */
export async function decideViaBrowser(
  page: Page,
  setup: MachineSetup,
  decision: 'approve' | 'deny',
): Promise<Approval> {
  const holder = await browserHolder(page)
  const pub = publicJwkFromPrivate(holder.privateJwk.d)
  const holderJwk = { kty: 'EC', crv: 'P-256', x: pub.x, y: pub.y }
  const credentialId = await issueCredential(setup, holderJwk, holder.privateJwk)
  const created = await createRequest(setup, credentialId)
  await reviewRequest(page, created, holder.thumbprint)
  await page
    .getByRole('button', { name: decision === 'approve' ? 'Approve and share' : 'Deny' })
    .click()
  if (decision === 'approve') {
    await expect(page.getByText('Verified — synthetic consent proof')).toBeVisible()
    expect(await fieldValue(page, 'Profile')).toBe(expectedProfile())
    expect((await fieldValue(page, 'Presentation')).split('.')).toHaveLength(3)
  } else {
    await expect(page.getByText('Denied — nothing was shared')).toBeVisible()
  }
  return {
    requestId: created.requestId,
    audience: AUDIENCE,
    thumbprint: holder.thumbprint,
    privateJwk: holder.privateJwk,
  }
}
